"use client";

import { motion, useReducedMotion } from "framer-motion";

export function TextGenerateEffect({ text }: { text: string }) {
  const words = text.split(" ");
  const shouldReduceMotion = useReducedMotion();

  return (
    <p className="leading-relaxed">
      {words.map((word, i) => (
        <motion.span
          key={i}
          className="mr-[0.3em] inline-block"
          initial={shouldReduceMotion ? { opacity: 1, filter: "blur(0px)" } : { opacity: 0, filter: "blur(6px)" }}
          whileInView={{ opacity: 1, filter: "blur(0px)" }}
          viewport={{ once: true, margin: "-10% 0px" }}
          transition={{ duration: 0.4, delay: shouldReduceMotion ? 0 : i * 0.08, ease: [0.22, 1, 0.36, 1] }}
        >
          {word}
        </motion.span>
      ))}
    </p>
  );
}
